#!/usr/bin/env node

import { build } from 'esbuild';
import { writeFileSync, mkdirSync, existsSync, readFileSync, statSync, readdirSync } from 'fs';
import { join, dirname, relative, extname, basename } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

class CSSBundler {
    constructor(basePath) {
        this.basePath = basePath;
        this.cssContent = new Map();
        this.componentCSSMap = new Map();
    }

    async findCSSFiles(dir) {
        const files = [];

        function scanDirectory(currentDir) {
            try {
                const entries = readdirSync(currentDir, { withFileTypes: true });

                for (const entry of entries) {
                    const fullPath = join(currentDir, entry.name);

                    if (entry.isDirectory()) {
                        // Пропускаем node_modules и скрытые папки
                        if (!entry.name.includes('node_modules') && !entry.name.startsWith('.')) {
                            scanDirectory(fullPath);
                        }
                    } else if (entry.isFile() && extname(entry.name) === '.css') {
                        files.push(fullPath);
                    }
                }
            } catch (error) {
                console.warn(`⚠️ Cannot scan directory ${currentDir}:`, error.message);
            }
        }

        scanDirectory(dir);
        return files;
    }

    async processCSSFiles(cssFiles) {
        for (const filePath of cssFiles) {
            try {
                const content = readFileSync(filePath, 'utf-8');
                const relativePath = relative(this.basePath, filePath);

                this.cssContent.set(relativePath, content);

                // Определяем к какому компоненту относится CSS
                const componentName = this.extractComponentName(relativePath);
                if (componentName) {
                    if (!this.componentCSSMap.has(componentName)) {
                        this.componentCSSMap.set(componentName, []);
                    }
                    this.componentCSSMap.get(componentName).push(relativePath);
                }
            } catch (error) {
                console.warn(`⚠️ Cannot read CSS file ${filePath}:`, error.message);
            }
        }
    }

    extractComponentName(cssPath) {
        const patterns = [
            /components\/([^\/]+)\/css\//,
            /src\/components\/([^\/]+)\/css\//,
            /components\/([^\/]+)\//,
            /([^\/]+)\/css\//
        ];

        for (const pattern of patterns) {
            const match = cssPath.match(pattern);
            if (match) {
                return match[1];
            }
        }

        // Если не нашли паттерн, используем имя директории
        const dirName = dirname(cssPath);
        return basename(dirName);
    }

    generateCSSBundle() {
        let bundle = '/* CSS Bundle - Generated by esbuild */\n\n';

        for (const [filePath, content] of this.cssContent) {
            bundle += `/* ${filePath} */\n`;
            bundle += content;
            bundle += '\n\n';
        }

        return bundle;
    }

    createCSSModule() {
        const cssBundle = this.generateCSSBundle();
        const cssPaths = Array.from(this.cssContent.keys());
        const componentMap = Object.fromEntries(this.componentCSSMap);

        return `\
const cssContent = ${JSON.stringify(cssBundle)};
const cssPaths = ${JSON.stringify(cssPaths)};
const componentCSSMap = ${JSON.stringify(componentMap)};

export function getCSSByPath(filePath) {
  const normalizedPath = filePath.replace(/\\\\/g, "/");
  const entry = cssPaths.find(path => path.replace(/\\\\/g, "/").includes(normalizedPath));
  
  if (entry) {
    const startMarker = "/* " + entry + " */";
    const startIndex = cssContent.indexOf(startMarker) + startMarker.length;
    let endIndex = cssContent.length;
    
    for (let i = cssPaths.indexOf(entry) + 1; i < cssPaths.length; i++) {
      const nextMarker = "/* " + cssPaths[i] + " */";
      const nextIndex = cssContent.indexOf(nextMarker);
      if (nextIndex !== -1) {
        endIndex = nextIndex;
        break;
      }
    }
    
    return cssContent.substring(startIndex, endIndex).trim();
  }
  return null;
}

export function getCSSForComponent(componentName) {
  const componentPaths = componentCSSMap[componentName];
  if (!componentPaths) return null;
  
  return componentPaths.map(path => getCSSByPath(path)).filter(Boolean).join("\\n");
}

export function getAllCSS() {
  return cssContent;
}

export function injectCSS() {
  if (typeof document !== "undefined") {
    const style = document.createElement("style");
    style.textContent = cssContent;
    document.head.appendChild(style);
  }
}

export function getCSSPaths() {
  return cssPaths;
}

export function getMultipleCSS(paths) {
  return paths.map(path => getCSSByPath(path)).filter(Boolean).join("\\n");
}

export function getComponentCSSMap() {
  return componentCSSMap;
}

export default cssContent;
`;
    }
}

class UniversalBundler {
    constructor() {
        this.projectRoot = process.cwd();
        this.distDir = join(this.projectRoot, 'bundle');
    }

    async createUniversalBundle(outputFileName = 'bundle', options = {}) {
        console.log('⚡ Creating universal bundle...');

        this.ensureDirectory(this.distDir);

        const entryPoint = join(this.projectRoot, 'src', 'index.ts');
        const entryPointJS = join(this.projectRoot, 'src', 'index.js');

        let entry = entryPoint;
        if (!existsSync(entryPoint) && existsSync(entryPointJS)) {
            entry = entryPointJS;
            console.log('📁 Using JavaScript entry point');
        }

        if (!existsSync(entry)) {
            console.error('❌ Entry point not found:', entry);
            process.exit(1);
        }

        console.log(`📁 Entry point: ${entry}`);
        console.log(`📁 Output directory: ${this.distDir}`);

        // Находим и обрабатываем CSS файлы только если включен флаг virtual-css
        let cssPlugin = null;
        if (options.virtualCss) {
            try {
                console.log('🎨 Looking for CSS files...');
                const cssBundler = new CSSBundler(this.projectRoot);
                const cssFiles = await cssBundler.findCSSFiles(join(this.projectRoot, 'src'));

                if (cssFiles.length > 0) {
                    console.log(`🎨 Found ${cssFiles.length} CSS files`);
                    await cssBundler.processCSSFiles(cssFiles);

                    cssPlugin = {
                        name: 'virtual-css',
                        setup(build) {
                            build.onResolve({ filter: /^virtual:css$/ }, args => {
                                return {
                                    path: 'virtual:css',
                                    namespace: 'virtual-css'
                                };
                            });

                            build.onLoad({ filter: /^virtual:css$/, namespace: 'virtual-css' }, () => {
                                const moduleContent = cssBundler.createCSSModule();
                                return {
                                    contents: moduleContent,
                                    loader: 'js'
                                };
                            });
                        }
                    };
                } else {
                    console.log('🎨 No CSS files found');
                }
            } catch (error) {
                console.warn('⚠️ CSS processing skipped:', error.message);
            }
        }

        try {
            if (options.browserOnly) {
                // Только браузерный бандл
                await this.buildBrowserBundle(entry, outputFileName, options, cssPlugin);

                console.log('\n✅ Browser-only bundle created:');
                console.log(`   📦 bundle/${outputFileName}.js (Browser)`);

                this.showFileSizesBrowserOnly(outputFileName);

            } else if (options.onlyMjs) {
                // Собираем Node.js бандлы (mjs и cjs)
                await this.buildNodeBundles(entry, outputFileName, options, cssPlugin);

                // Собираем браузерный бандл только если не только mjs
                if (!options.onlyMjs) {
                    await this.buildBrowserBundle(entry, outputFileName, options, cssPlugin);
                }

                console.log('\n✅ Universal bundles created:');
                if (options.onlyMjs) {
                    console.log(`   📦 bundle/${outputFileName}.mjs (ES Modules only)`);
                } else {
                    console.log(`   📦 bundle/${outputFileName}.mjs (ES Modules)`);
                    console.log(`   📦 bundle/${outputFileName}.cjs (CommonJS)`);
                    console.log(`   📦 bundle/${outputFileName}.browser.js (Browser)`);
                }

                this.generateBuildInfo(outputFileName, options);
                this.showFileSizes(outputFileName, options);

            } else {
                // Собираем Node.js бандлы (mjs и cjs)
                await this.buildNodeBundles(entry, outputFileName, options, cssPlugin);

                // Собираем браузерный бандл
                await this.buildBrowserBundle(entry, outputFileName, options, cssPlugin);

                console.log('\n✅ Universal bundles created:');
                console.log(`   📦 bundle/${outputFileName}.mjs (ES Modules)`);
                console.log(`   📦 bundle/${outputFileName}.cjs (CommonJS)`);
                console.log(`   📦 bundle/${outputFileName}.browser.js (Browser)`);

                this.generateBuildInfo(outputFileName, options);
                this.showFileSizes(outputFileName, options);
            }

        } catch (error) {
            console.error('❌ Bundle creation failed:', error);
            if (error.errors) {
                error.errors.forEach(err => console.error('   -', err.text));
            }
            process.exit(1);
        }
    }

    async buildNodeBundles(entry, outputFileName, options, cssPlugin) {
        // Получаем зависимости для Node.js
        const external = this.getNodeExternals();
        console.log(`📦 Node.js external dependencies: ${external.length > 0 ? external.join(', ') : 'none'}`);

        // ESM для Node.js
        const esmConfig = {
            entryPoints: [entry],
            bundle: true,
            outfile: join(this.distDir, `${outputFileName}.mjs`),
            platform: 'node',
            format: 'esm',
            minify: options.minify !== false,
            treeShaking: true,
            target: 'node18',
            sourcemap: true,
            external,
            define: {
                'process.env.NODE_ENV': '"production"'
            },
            plugins: cssPlugin ? [cssPlugin] : [],
            legalComments: 'none'
        };

        await build(esmConfig);
        console.log(`   ✅ bundle/${outputFileName}.mjs (ES Modules)`);

        // CommonJS для Node.js (если не только mjs и не browser-only)
        if (!options.onlyMjs && !options.browserOnly) {
            const cjsConfig = {
                ...esmConfig,
                outfile: join(this.distDir, `${outputFileName}.cjs`),
                format: 'cjs'
            };

            await build(cjsConfig);
            console.log(`   ✅ bundle/${outputFileName}.cjs (CommonJS)`);
        }
    }

    async buildBrowserBundle(entry, outputFileName, options, cssPlugin) {
        try {
            // Проверяем, можно ли собрать для браузера
            const canBuildForBrowser = await this.canBuildForBrowser(entry);
            if (!canBuildForBrowser) {
                console.log('   ⚠️ Browser bundle skipped - contains Node.js specific code');
                return;
            }

            // Для браузера используем минимальный список external
            const external = this.getBrowserExternals();
            console.log(`🌐 Browser external dependencies: ${external.length > 0 ? external.join(', ') : 'none'}`);

            const browserConfig = {
                entryPoints: [entry],
                bundle: true,
                outfile: join(this.distDir, `${outputFileName}${options.browserOnly ? '.js' : '.browser.js'}`),
                platform: 'browser',
                format: 'iife',
                minify: options.minify !== false,
                treeShaking: true,
                target: 'es2020',
                sourcemap: true,
                external,
                globalName: this.getGlobalName(outputFileName),
                define: {
                    'process.env.NODE_ENV': '"production"'
                },
                plugins: cssPlugin ? [cssPlugin] : [],
                legalComments: 'none'
            };

            await build(browserConfig);
            console.log(`   ✅ bundle/${outputFileName}${options.browserOnly ? '.js' : '.browser.js'} (Browser)`);

        } catch (error) {
            console.warn(`   ⚠️ Browser bundle failed: ${error.message}`);
        }
    }

    async canBuildForBrowser(entry) {
        try {
            const content = readFileSync(entry, 'utf-8');

            // Проверяем наличие Node.js специфичного кода
            const nodePatterns = [
                /require\(/,
                /import.*from\s+['"]node:/,
                /import.*from\s+['"]fs['"]/,
                /import.*from\s+['"]path['"]/,
                /import.*from\s+['"]os['"]/,
                /import.*from\s+['"]util['"]/,
                /import.*from\s+['"]process['"]/,
                /import.*from\s+['"]child_process['"]/,
                /process\.env/,
                /__dirname/,
                /__filename/
            ];

            return !nodePatterns.some(pattern => pattern.test(content));
        } catch {
            return false;
        }
    }

    getNodeExternals() {
        // Все Node.js built-in модули
        const nodeBuiltIns = [
            // Node.js built-in modules
            'fs', 'path', 'os', 'child_process', 'crypto', 'http', 'https',
            'net', 'dns', 'url', 'util', 'stream', 'buffer', 'events',
            'module', 'assert', 'querystring', 'zlib', 'tls', 'cluster',
            'vm', 'perf_hooks', 'readline', 'repl', 'timers', 'string_decoder',
            'process',

            // Node.js built-in modules with node: prefix
            'node:fs', 'node:path', 'node:os', 'node:child_process', 'node:crypto',
            'node:http', 'node:https', 'node:net', 'node:dns', 'node:url',
            'node:util', 'node:stream', 'node:buffer', 'node:events',
            'node:tty', 'node:readline', 'node:repl', 'node:cluster',
            'node:perf_hooks', 'node:worker_threads', 'node:v8', 'node:process'
        ];

        // Пытаемся получить зависимости из package.json
        const packageDeps = this.getPackageDependencies();

        return [...nodeBuiltIns, ...packageDeps];
    }

    getBrowserExternals() {
        // Для браузера - только Node.js built-in модули
        const browserExternals = [
            // Node.js built-ins
            'fs', 'path', 'os', 'child_process', 'crypto', 'http', 'https',
            'net', 'dns', 'url', 'util', 'stream', 'buffer', 'events',
            'module', 'assert', 'querystring', 'zlib', 'tls', 'cluster',
            'vm', 'perf_hooks', 'readline', 'repl', 'timers', 'string_decoder',
            'process',

            // Node.js built-ins with node: prefix
            'node:fs', 'node:path', 'node:os', 'node:child_process', 'node:crypto',
            'node:http', 'node:https', 'node:net', 'node:dns', 'node:url',
            'node:util', 'node:stream', 'node:buffer', 'node:events',
            'node:tty', 'node:readline', 'node:repl', 'node:cluster',
            'node:perf_hooks', 'node:worker_threads', 'node:v8', 'node:process'
        ];

        return browserExternals;
    }

    getPackageDependencies() {
        try {
            const packageJsonPath = join(this.projectRoot, 'package.json');
            if (existsSync(packageJsonPath)) {
                const packageJson = JSON.parse(readFileSync(packageJsonPath, 'utf-8'));
                const allDeps = [
                    ...Object.keys(packageJson.dependencies || {}),
                    ...Object.keys(packageJson.devDependencies || {}),
                    ...Object.keys(packageJson.peerDependencies || {})
                ];

                return allDeps.filter(dep =>
                    !dep.startsWith('.') &&
                    !dep.startsWith('/') &&
                    !dep.startsWith('file:')
                );
            }
        } catch (error) {
            console.warn('   ⚠️ Could not read package.json');
        }

        return [];
    }

    getGlobalName(outputFileName) {
        return outputFileName
            .split(/[-_]/)
            .map((word, index) =>
                index === 0 ? word.toLowerCase() : word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()
            )
            .join('');
    }

    generateBuildInfo(outputFileName, options) {
        const buildInfo = {
            name: outputFileName,
            timestamp: new Date().toISOString(),
            files: {
                esm: `${outputFileName}.mjs`,
                ...(options.onlyMjs ? {} : {
                    cjs: `${outputFileName}.cjs`,
                    browser: `${outputFileName}.browser.js`
                })
            },
            build: {
                tool: 'esbuild',
                target: 'node18',
                format: options.onlyMjs ? ['esm'] : ['esm', 'cjs', 'iife'],
                minify: options.minify !== false,
                treeShaking: true,
                onlyMjs: options.onlyMjs || false,
                virtualCss: options.virtualCss || false,
                browserOnly: options.browserOnly || false
            },
            externalDependencies: this.getPackageDependencies(),
            node: true
        };

        writeFileSync(
            join(this.distDir, `${outputFileName}.info.json`),
            JSON.stringify(buildInfo, null, 2)
        );

        console.log(`   📄 bundle/${outputFileName}.info.json (Build info)`);
    }

    showFileSizes(outputFileName, options) {
        const files = [
            `${outputFileName}.mjs`,
            ...(options.onlyMjs ? [] : [
                `${outputFileName}.cjs`,
                `${outputFileName}.browser.js`
            ]),
            `${outputFileName}.info.json`
        ];

        console.log('\n📊 File sizes:');
        let hasFiles = false;

        files.forEach(file => {
            const filePath = join(this.distDir, file);
            if (existsSync(filePath)) {
                const stats = statSync(filePath);
                const size = (stats.size / 1024).toFixed(2);
                console.log(`   ${file}: ${size} KB`);
                hasFiles = true;
            }
        });

        if (!hasFiles) {
            console.log('   ⚠️ No bundle files were created');
        }
    }

    showFileSizesBrowserOnly(outputFileName) {
        const files = [
            `${outputFileName}.js`,
            `${outputFileName}.info.json`
        ];

        console.log('\n📊 File sizes:');
        let hasFiles = false;

        files.forEach(file => {
            const filePath = join(this.distDir, file);
            if (existsSync(filePath)) {
                const stats = statSync(filePath);
                const size = (stats.size / 1024).toFixed(2);
                console.log(`   ${file}: ${size} KB`);
                hasFiles = true;
            }
        });

        if (!hasFiles) {
            console.log('   ⚠️ No bundle files were created');
        }
    }

    ensureDirectory(path) {
        if (!existsSync(path)) {
            mkdirSync(path, { recursive: true });
        }
    }
}

// CLI обработчик
async function main() {
    const args = process.argv.slice(2);
    let outputFileName = 'example';
    const options = {
        onlyMjs: false,
        browserOnly: false,
        virtualCss: false,
        minify: true
    };

    // Парсим аргументы командной строки
    for (let i = 0; i < args.length; i++) {
        const arg = args[i];

        switch (arg) {
            case '--help':
            case '-h':
                showHelp();
                return;

            case '--output':
            case '-o':
                outputFileName = args[++i] || 'bundle';
                outputFileName = outputFileName.replace(/\.[^/.]+$/, '');
                break;

            case '--name':
            case '-n':
                outputFileName = args[++i] || 'bundle';
                break;

            case '--only-mjs':
            case '--esm-only':
                options.onlyMjs = true;
                break;

            case '--browser-only':
                options.browserOnly = true;
                break;

            case '--virtual-css':
                options.virtualCss = true;
                break;

            case '--no-minify':
                options.minify = false;
                break;

            default:
                if (!arg.startsWith('-')) {
                    outputFileName = arg.replace(/\.[^/.]+$/, '');
                }
                break;
        }
    }

    console.log('📦 Bundling configuration:');
    console.log(`   Output: ${outputFileName}`);
    console.log(`   Only ESM: ${options.onlyMjs ? 'Yes' : 'No'}`);
    console.log(`   Browser only: ${options.browserOnly ? 'Yes' : 'No'}`);
    console.log(`   Virtual CSS: ${options.virtualCss ? 'Yes' : 'No'}`);
    console.log(`   Minify: ${options.minify ? 'Yes' : 'No'}`);

    const bundler = new UniversalBundler();
    await bundler.createUniversalBundle(outputFileName, options);
}

function showHelp() {
    console.log(`
🚀 Universal Project Bundler

Универсальный сборщик для проектов с точкой входа ./src/index.ts или ./src/index.js

ИСПОЛЬЗОВАНИЕ:
  node scripts/bundle.js [options] [output-name]

ОПЦИИ:
  -h, --help           Показать эту справку
  -o, --output <name>  Имя выходного файла (без расширения)
  -n, --name <name>    Альтернативное указание имени
  --only-mjs           Создать только ESM бандл (.mjs) для Node.js
  --browser-only       Создать только браузерный бандл (.js)
  --esm-only           Alias для --only-mjs
  --virtual-css        Включить поддержку virtual:css модуля
  --no-minify          Отключить минификацию

ПРИМЕРЫ:
  # Только браузерный бандл с CSS
  node scripts/bundle.js --browser-only --virtual-css

  # Браузерный бандл с кастомным именем
  node scripts/bundle.js --browser-only --output app

  # Только ESM для Node.js с CSS
  node scripts/bundle.js --esm-only --virtual-css

  # Все форматы (по умолчанию)
  node scripts/bundle.js --virtual-css

  # Сборка всех форматов без минификации
  node scripts/bundle.js --no-minify

СОЗДАВАЕМЫЕ ФАЙЛЫ:
  • bundle/<name>.js          - Браузерная версия (только с --browser-only)
  • bundle/<name>.mjs         - ES Modules версия (Node.js)
  • bundle/<name>.cjs         - CommonJS версия (Node.js) [если не --only-mjs]
  • bundle/<name>.browser.js  - Browser версия [если не --only-mjs и не --browser-only]
  • bundle/<name>.info.json   - Информация о сборке

ОСОБЕННОСТИ:
  • Автоматическое определение внешних зависимостей
  • Tree shaking и минификация (по умолчанию включена)
  • Source maps для отладки
  • Статистика размеров файлов
  • Поддержка Node.js и браузера
  • Виртуальный модуль CSS (virtual:css) по флагу --virtual-css
    `.trim());
}

// Запуск
main().catch(error => {
    console.error('❌ Fatal error:', error);
    process.exit(1);
});

export { UniversalBundler };